#include <iostream>
#include <array>

// Checks if the first element equals the second element (O(1) runtime)
template <typename T, std::size_t N>
bool areFirstTwoEqual(const std::array<T, N>& items) {
    static_assert(N >= 2, "Array must contain at least 2 elements");
    return items[0] == items[1]; // Always 1 comparison regardless of N
}

int main() {
    std::array<int, 4> firstArr{10, 10, 20, 30};
    std::array<int, 8> secondArr{1, 2, 3, 4, 5, 6, 7, 8};

    std::cout << std::boolalpha;
    std::cout << "firstArr first two equal: " << areFirstTwoEqual(firstArr) << "\n";
    std::cout << "secondArr first two equal: " << areFirstTwoEqual(secondArr) << "\n";

    return 0;
}

