// Linear search of an array.
#include <iostream>
#include <array>

// compare key to every element of array until location is
// found or until end of array is reached; return location of
// element if key is found or -1 if key is not found
template <typename T, std::size_t size>
int linearSearch(const std::array<T, size>& items, const T& key) {
    for (std::size_t i = 0; i < items.size(); ++i) {
        if (key == items[i]) { // if found,
            return static_cast<int>(i); // return location of key
        }
    }

    return -1; // key not found
} // end function linearSearch

int main() {
    const std::size_t arraySize = 100; // size of array
    std::array<int, arraySize> arrayToSearch; // create array

    for (std::size_t i = 0; i < arrayToSearch.size(); ++i) {
        arrayToSearch[i] = 2 * static_cast<int>(i); // create some data
    }

    int searchKey;
    while (std::cin >> searchKey) {
        std::cout << "Enter integer search key: " << searchKey << "\n";

        // attempt to locate searchKey in arrayToSearch
        int element = linearSearch(arrayToSearch, searchKey);

        // display results
        if (element != -1) {
            std::cout << "Found value in element " << element << "\n";
        } else {
            std::cout << "Value not found\n";
        }
    }

    return 0;
} // end main
